it('registers through its service provider and merges its config', function () {
    TestApp::boot();
    expect(config('connectors.resend.mode'))->toBe('auto');
    expect(config('connectors.resend.credentials'))->toBeArray();
});

it('fakes attachment_get and records it for assertSent', function () {
    TestApp::boot();
    Resend::fake();
    $config = [
        'emailId' => 'example-emailId',
        'attachmentId' => 'example-attachmentId',
    ];
    $result = Resend::call('attachment_get', $config);

    expect($result->mode->value)->toBe('fake');
    Resend::assertSent('attachment_get', fn (array $sent): bool => $sent == $config);
    Resend::assertNotSent('no_such_operation');
    Resend::assertSentCount(1);
});

it('refuses a forged email_received delivery before the app sees it', function () {
    $app = TestApp::boot();
    $app['router']->resendEmailReceived('/hooks/resend');
    $response = TestApp::dispatch($app, Request::create('/hooks/resend', 'POST', server: ['CONTENT_TYPE' => 'application/json'], content: '{"forged":true}'));

    expect($response->getStatusCode())->toBe(401);
});
